CREATE OR REPLACE FUNCTION public.is_webmaster() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS (SELECT 1 FROM public.profiles WHERE user_id = auth.uid() AND sales_role = 'webmaster'); $$;
REVOKE ALL ON FUNCTION public.is_webmaster() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.is_webmaster() TO authenticated, service_role;
CREATE TABLE public.finance_projects (id text PRIMARY KEY, name text NOT NULL, status text NOT NULL DEFAULT 'needs checking', terms jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.finance_projects TO authenticated; GRANT ALL ON public.finance_projects TO service_role;
ALTER TABLE public.finance_projects ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.finance_counterparties (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), kind text NOT NULL DEFAULT 'client' CHECK (kind IN ('client','vendor','employee')), name text NOT NULL, contact text, memo text, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.finance_counterparties TO authenticated; GRANT ALL ON public.finance_counterparties TO service_role;
ALTER TABLE public.finance_counterparties ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.finance_tasks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id text REFERENCES public.finance_projects(id), name text NOT NULL, due_date date, status text NOT NULL DEFAULT 'needs checking' CHECK (status IN ('confirmed','assumed','needs checking','decision needed','delay risk','done')), note text, source_url text, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.finance_tasks TO authenticated; GRANT ALL ON public.finance_tasks TO service_role;
ALTER TABLE public.finance_tasks ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.finance_documents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id text REFERENCES public.finance_projects(id), name text NOT NULL, version text, doc_date date, type text NOT NULL DEFAULT 'contract' CHECK (type IN ('contract','proposal','invoice','evidence','other')), status text NOT NULL DEFAULT 'needs checking', source_url text, file_path text, terms jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.finance_documents TO authenticated; GRANT ALL ON public.finance_documents TO service_role;
ALTER TABLE public.finance_documents ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.finance_monthly_actuals (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id text NOT NULL REFERENCES public.finance_projects(id), month date NOT NULL, currency text NOT NULL DEFAULT 'KRW' CHECK (currency IN ('KRW','USD')), actual_paid numeric(18,2) NOT NULL DEFAULT 0 CHECK (actual_paid >= 0), actual_received numeric(18,2) NOT NULL DEFAULT 0 CHECK (actual_received >= 0), average_power_kw numeric NOT NULL DEFAULT 1500 CHECK (average_power_kw >= 0), note text, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(project_id, month));
GRANT SELECT, INSERT, UPDATE, DELETE ON public.finance_monthly_actuals TO authenticated; GRANT ALL ON public.finance_monthly_actuals TO service_role;
ALTER TABLE public.finance_monthly_actuals ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.finance_entries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), kind text NOT NULL DEFAULT 'receivable' CHECK (kind IN ('receivable','payable')), counterparty_id uuid NOT NULL REFERENCES public.finance_counterparties(id), project_id text REFERENCES public.finance_projects(id), description text NOT NULL, amount numeric(18,2) NOT NULL DEFAULT 0 CHECK (amount >= 0), currency text NOT NULL DEFAULT 'KRW' CHECK (currency IN ('KRW','USD')), issue_date date NOT NULL DEFAULT CURRENT_DATE, due_date date, status text NOT NULL DEFAULT 'scheduled' CHECK (status IN ('scheduled','invoiced','received','paid','overdue')), paid_date date, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.finance_entries TO authenticated; GRANT ALL ON public.finance_entries TO service_role;
ALTER TABLE public.finance_entries ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.finance_expenses (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), date date NOT NULL DEFAULT CURRENT_DATE, project_id text REFERENCES public.finance_projects(id), category text NOT NULL DEFAULT 'expense' CHECK (category IN ('payroll','commission','expense','other')), payee_name text NOT NULL, amount numeric(18,2) NOT NULL DEFAULT 0 CHECK (amount >= 0), currency text NOT NULL DEFAULT 'KRW' CHECK (currency IN ('KRW','USD')), status text NOT NULL DEFAULT 'scheduled' CHECK (status IN ('scheduled','paid')), memo text, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.finance_expenses TO authenticated; GRANT ALL ON public.finance_expenses TO service_role;
ALTER TABLE public.finance_expenses ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.finance_company (id integer PRIMARY KEY DEFAULT 1 CHECK (id = 1), name text NOT NULL DEFAULT 'Namsan Korea Co., Ltd.', legal_name_ko text NOT NULL DEFAULT '', ceo text NOT NULL DEFAULT 'Sung Kwang-ju', address text NOT NULL DEFAULT '', registration_number text NOT NULL DEFAULT '', updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.finance_company TO authenticated; GRANT ALL ON public.finance_company TO service_role;
ALTER TABLE public.finance_company ENABLE ROW LEVEL SECURITY;
CREATE SEQUENCE public.finance_invoice_sequence;
REVOKE ALL ON SEQUENCE public.finance_invoice_sequence FROM PUBLIC, anon;
GRANT USAGE ON SEQUENCE public.finance_invoice_sequence TO authenticated, service_role;
CREATE TABLE public.finance_invoices (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id text REFERENCES public.finance_projects(id), invoice_number text NOT NULL UNIQUE DEFAULT ('NK-' || to_char(now() AT TIME ZONE 'Asia/Seoul','YYYYMMDD') || '-' || lpad(nextval('public.finance_invoice_sequence')::text,3,'0')), issue_date date NOT NULL DEFAULT CURRENT_DATE, due_date date, status text NOT NULL DEFAULT 'draft', snapshot jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.finance_invoices TO authenticated; GRANT ALL ON public.finance_invoices TO service_role;
ALTER TABLE public.finance_invoices ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.finance_history (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id text, action text NOT NULL, target_table text NOT NULL, target_id text, before_values jsonb, after_values jsonb, actor_email text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.finance_history TO authenticated; GRANT ALL ON public.finance_history TO service_role;
ALTER TABLE public.finance_history ENABLE ROW LEVEL SECURITY;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['finance_projects','finance_counterparties','finance_tasks','finance_documents','finance_monthly_actuals','finance_entries','finance_expenses','finance_company','finance_invoices','finance_history'] LOOP
EXECUTE format('CREATE POLICY webmaster_select ON public.%I FOR SELECT TO authenticated USING (public.is_webmaster())',t);
EXECUTE format('CREATE POLICY webmaster_insert ON public.%I FOR INSERT TO authenticated WITH CHECK (public.is_webmaster())',t);
EXECUTE format('CREATE POLICY webmaster_update ON public.%I FOR UPDATE TO authenticated USING (public.is_webmaster()) WITH CHECK (public.is_webmaster())',t);
EXECUTE format('CREATE POLICY webmaster_delete ON public.%I FOR DELETE TO authenticated USING (public.is_webmaster())',t);
END LOOP; END $$;
CREATE OR REPLACE FUNCTION public.finance_audit_mutation() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE b jsonb; a jsonb; row_data jsonb; BEGIN
IF TG_OP <> 'INSERT' THEN b := to_jsonb(OLD); END IF;
IF TG_OP <> 'DELETE' THEN a := to_jsonb(NEW); END IF;
row_data := COALESCE(a,b);
INSERT INTO public.finance_history(project_id,action,target_table,target_id,before_values,after_values,actor_email) VALUES(CASE WHEN TG_TABLE_NAME = 'finance_projects' THEN row_data->>'id' ELSE row_data->>'project_id' END,TG_OP,TG_TABLE_NAME,row_data->>'id',b,a,COALESCE(auth.jwt()->>'email','system'));
IF TG_OP = 'DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
END $$;
REVOKE ALL ON FUNCTION public.finance_audit_mutation() FROM PUBLIC, anon, authenticated;
CREATE OR REPLACE FUNCTION public.finance_history_guard() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$ BEGIN
IF TG_OP IN ('UPDATE','DELETE') THEN RAISE EXCEPTION 'Finance history is append-only'; END IF;
IF pg_trigger_depth() < 2 AND auth.role() IS DISTINCT FROM 'service_role' AND auth.uid() IS NOT NULL THEN RAISE EXCEPTION 'Finance history is written only by audit triggers'; END IF;
RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.finance_history_guard() FROM PUBLIC, anon, authenticated;
CREATE TRIGGER finance_history_immutable BEFORE INSERT OR UPDATE OR DELETE ON public.finance_history FOR EACH ROW EXECUTE FUNCTION public.finance_history_guard();
CREATE OR REPLACE FUNCTION public.finance_validate_money() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$ DECLARE r jsonb := to_jsonb(NEW); field text; value numeric; BEGIN
IF r->>'currency' = 'KRW' THEN FOREACH field IN ARRAY ARRAY['amount','actual_paid','actual_received'] LOOP IF r ? field THEN value := (r->>field)::numeric; IF value <> trunc(value) THEN RAISE EXCEPTION 'KRW amounts must be whole integers'; END IF; END IF; END LOOP; END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.finance_validate_money() FROM PUBLIC, anon, authenticated;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['finance_projects','finance_counterparties','finance_tasks','finance_documents','finance_monthly_actuals','finance_entries','finance_expenses','finance_company','finance_invoices'] LOOP EXECUTE format('CREATE TRIGGER finance_audit AFTER INSERT OR UPDATE OR DELETE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.finance_audit_mutation()',t); END LOOP;
FOREACH t IN ARRAY ARRAY['finance_monthly_actuals','finance_entries','finance_expenses'] LOOP EXECUTE format('CREATE TRIGGER finance_money BEFORE INSERT OR UPDATE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.finance_validate_money()',t); END LOOP; END $$;